#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,subprocess,sys,tempfile,hashlib
target=Path(sys.argv[1]).resolve()
root=target.parent.parent
expected_base="ffc5721eca68844357dbdca63b0edf266e7e210f9d162eecde8cae0067f210a8"
expected_out="82594aaea923a2a19c06eadb73d8d985941b392c56b8c613866b5a99523ae806"
if hashlib.sha256(target.read_bytes()).hexdigest()!=expected_base:
    raise SystemExit("unexpected base kernel hash")
data=gzip.decompress(base64.b64decode("""""")).decode()
with tempfile.NamedTemporaryFile('w',delete=False) as f:
    f.write(data); p=f.name
subprocess.run(['patch','-p1','--forward','--batch','-i',p],cwd=root,check=True)
actual=hashlib.sha256(target.read_bytes()).hexdigest()
if actual!=expected_out:
    raise SystemExit(f"patched hash mismatch {actual}")
print('patched',target)
